function validate([n, edges]) {
  if (!Number.isInteger(n) || n < 1 || n > 1000) return 'n is between 1 and 1000.';
  if (!Array.isArray(edges) || edges.length > Math.min(2000, n * (n - 1) / 2)) return 'edges has at most min(2000, n * (n - 1) / 2) entries.';
  const seen = new Set();
  const children = Array.from({ length: n }, () => []);
  const indegree = new Array(n).fill(0);
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [from, to].';
    const [from, to] = edge;
    if (![from, to].every(v => Number.isInteger(v) && v >= 0 && v < n)) return 'Edge endpoints are nodes 0 to n - 1.';
    if (from === to) return 'An edge cannot point to its own node.';
    if (seen.has(from * n + to)) return 'Edges must not repeat.';
    seen.add(from * n + to);
    children[from].push(to);
    indegree[to]++;
  }
  const queue = [];
  for (let i = 0; i < n; i++) if (indegree[i] === 0) queue.push(i);
  let removed = 0;
  for (let head = 0; head < queue.length; head++) {
    removed++;
    for (const next of children[queue[head]]) if (--indegree[next] === 0) queue.push(next);
  }
  if (removed !== n) return 'The graph must not contain a cycle.';
  return null;
}

