function getAncestors(n, edges) {
  const reach = Array.from({ length: n }, () => new Array(n).fill(false));
  for (const [a, b] of edges) reach[a][b] = true;
  for (let k = 0; k < n; k++)
    for (let i = 0; i < n; i++)
      if (reach[i][k])
        for (let j = 0; j < n; j++)
          if (reach[k][j]) reach[i][j] = true;
  const result = [];
  for (let v = 0; v < n; v++) {
    const list = [];
    for (let u = 0; u < n; u++) if (reach[u][v]) list.push(u);
    result.push(list);
  }
  return result;
}

