function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 200 + Math.floor(rand() * 801) : 1 + Math.floor(rand() * 7);
  const limit = Math.min(2000, n * (n - 1) / 2);
  // Edges only go forward in a hidden order, so the graph stays acyclic. Large inputs are split into
  // groups of consecutive ranks with no edges between them, which keeps the answer lists a readable size.
  const group = large ? 10 + Math.floor(rand() * 50) : n;
  let capacity = 0;
  for (let a = 0; a < n; a++) capacity += Math.min(group - 1 - (a % group), n - 1 - a);
  const wanted = large ? Math.floor(limit * (0.5 + rand() * 0.5)) : Math.floor(rand() * (limit + 1));
  const m = Math.min(wanted, large ? Math.floor(capacity * 0.8) : capacity);
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  const seen = new Set();
  const edges = [];
  while (edges.length < m) {
    const a = Math.floor(rand() * n);
    const b = a + 1 + Math.floor(rand() * (group - 1 - (a % group)));
    if (b >= n || b === a + group - (a % group) || seen.has(a * n + b)) continue;
    seen.add(a * n + b);
    edges.push([order[a], order[b]]);
  }
  return [n, edges];
}
